OUT=Path(sys.argv[1]);OUT.mkdir(parents=True,exist_ok=True);inner='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 40 40"><rect width="40" height="40"/><circle cx="30" cy="10" r="5" fill="white"/></svg>';u='data:image/svg+xml;base64,'+base64.b64encode(inner.encode()).decode();s=f'<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="240" height="160"><defs><symbol id="s" viewBox="0 0 40 40"><rect width="40" height="40"/><circle cx="30" cy="10" r="5" fill="white"/></symbol></defs><use xlink:href="#s" x="10" y="10" width="60" fill="#ff0000"/><use xlink:href="#s" x="100" y="20" height="80" fill="#0000ff"/><image x="180" y="10" width="40" height="40" xlink:href="{u}"/></svg>';d=cairosvg.svg2png(bytestring=s.encode());(OUT/'instances.svg').write_text(s);(OUT/'instances.png').write_bytes(d);im=Image.open(BytesIO(d)).convert('RGBA');checks=[{'name':'red-instance','actual':im.getpixel((30,80)),'passed':im.getpixel((30,80))[:3]==(255,0,0)},{'name':'blue-partial-size','actual':im.getpixel((190,60)),'passed':im.getpixel((190,60))[:3]==(0,0,255)},{'name':'sibling','actual':im.getpixel((195,20)),'passed':im.getpixel((195,20))[3]>0}];r={'source':cairosvg.__file__,'tests':3,'passed':sum(x['passed'] for x in checks),'failed':sum(not x['passed'] for x in checks),'checks':checks};(OUT/'result.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n');print(json.dumps(r,ensure_ascii=False,indent=2));(OUT/'gallery.html').write_text('<!doctype html><meta charset="utf-8"><title>实例引用</title><style>body{font:20px system-ui}img{width:600px;image-rendering:pixelated}</style><h1>symbol/use实际PNG</h1><img src="instances.png"><pre>'+json.dumps(r,ensure_ascii=False,indent=2)+'</pre>');sys.exit(bool(r['failed']))
